async () => {
  const namespaces = (await cloudflare.request({ method: 'GET', path: `/accounts/${accountId}/storage/kv/namespaces` })).result;
  const ns = namespaces.find(n => n.title === 'storefront-flags');
  const path = `/accounts/${accountId}/storage/kv/namespaces/${ns.id}/values/checkout_v2`;
  const current = JSON.parse((await cloudflare.request({ method: 'GET', path })).result);
  const next = { ...current, enabled: true, rollout: 25 };
  const metadata = (await cloudflare.request({ method: 'GET', path: `/accounts/${accountId}/storage/kv/namespaces/${ns.id}/metadata/checkout_v2` })).result;
  const form = new FormData();
  form.set('value', JSON.stringify(next));
  form.set('metadata', JSON.stringify(metadata));
  await cloudflare.request({ method: 'PUT', path, body: form });
  return { namespace: ns.id, before: current, after: next };
}
